const prompt = $json.prompt;

// 1. Regex PII Check (CPF, CNPJ, Phone)
const piiRegex = new RegExp(process.env.GUARDRAIL_PII_REGEX || '(?:\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}|\\d{11})');
const pii = prompt.match(piiRegex);
if (pii) {
  return [{ json: { safe: false, reason: 'PII detectado: Dados sensíveis encontrados.' } }];
}

// 2. Anti-injection Check
const injectionKeywords = ['ignore previous', 'system prompt', 'jailbreak'];
if (injectionKeywords.some(kw => prompt.toLowerCase().includes(kw))) {
  return [{ json: { safe: false, reason: 'Tentativa de Injection detectada.' } }];
}

// 3. Token Limit Check (Apróx)
if (prompt.length > (process.env.GUARDRAIL_MAX_TOKENS * 4 || 16000)) {
  return [{ json: { safe: false, reason: 'Limite de tokens excedido.' } }];
}

return [{ json: { safe: true, clean_prompt: 'Você é o assistente oficial Use Nexo. Responda de forma profissional. Contexto: ' + prompt } }];
